            position: relative;
            overflow-x: hidden;
        }

        /* 背景动态效果 */
        body::before {
            content: '';
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background:
                radial-gradient(circle at 20% 30%, rgba(100,255,218,0.05) 0%, transparent 50%),
                radial-gradient(circle at 80% 70%, rgba(199,146,234,0.05) 0%, transparent 50%);
            pointer-events: none;
            animation: bgShift 15s ease-in-out infinite alternate;
        }

        @keyframes bgShift {
            0% { transform: scale(1); }
            100% { transform: scale(1.1); }
        }

        .container {
            max-width: 1200px;
            margin: 0 auto;
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 20px;
        }

        .status-card {
            background: var(--card);
            border-radius: 12px;
            padding: 20px;
            position: relative;
            overflow: hidden;
            transition: all 0.3s ease;
            height: fit-content;
        }

        .status-card::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 2px;
            background: linear-gradient(90deg, var(--primary), var(--secondary));
            transform: scaleX(0);
            transform-origin: left;
            transition: transform 0.6s ease;
        }

        .status-card:hover::before {
            transform: scaleX(1);
        }

        .status-title {
            color: var(--primary);
            font-size: 1.2em;
            margin-bottom: 15px;
            display: flex;
            align-items: center;
            gap: 10px;
            cursor: pointer;
        }

        .status-content {
            max-height: 0;
            overflow-y: auto;
            transition: max-height 0.3s ease-out;
            scrollbar-width: thin;
            scrollbar-color: var(--primary) var(--card);
        }

        .status-content::-webkit-scrollbar {
            width: 6px;
        }

        .status-content::-webkit-scrollbar-track {
            background: var(--card);
            border-radius: 3px;
        }

        .status-content::-webkit-scrollbar-thumb {
            background: var(--primary);
            border-radius: 3px;
        }

        .status-content.expanded {
            max-height: 400px;
            transition: max-height 0.6s ease-in;
        }

        .status-item {
            display: flex;
            align-items: flex-start;
            margin: 10px 0;
            padding: 8px;
            border-radius: 8px;
            background: rgba(255,255,255,0.03);
            transition: all 0.3s ease;
        }

        .status-emoji {
            flex-shrink: 0;
            margin-right: 12px;
            font-size: 1.2em;
            opacity: 0.9;
        }

        .status-text {
            flex: 1;
            line-height: 1.6;
            word-break: break-word;
            white-space: pre-wrap;
            padding: 5px 0;
        }

        .expand-icon {
            margin-left: auto;
            transition: transform 0.3s ease;
        }

        .expanded .expand-icon {
            transform: rotate(180deg);
        }

        /* 关系互动和场景氛围的特殊样式 */
        .interaction-card,
        .atmosphere-card {
            grid-column: 1 / -1;
            max-width: 100%;
        }

        .interaction-content,
        .atmosphere-content {
            padding: 10px;
            background: rgba(255,255,255,0.02);
            border-radius: 8px;
            margin-top: 10px;
        }

        /* 添加滚动提示 */
        .status-content.expanded::after {
            content: '';
            position: absolute;
            bottom: 0;
            left: 0;
            right: 0;
            height: 30px;
            background: linear-gradient(transparent, var(--card));
            pointer-events: none;
            opacity: 0.8;
        }

        @media (max-width: 768px) {
            .container {
                grid-template-columns: 1fr;
            }

            body {
                padding: 10px;
            }

            .status-card {
                padding: 15px;
            }
        }
    </style>
