    <div class="container" id="status-container"></div>

    <script>
        const rules = {
            environment: {
                pattern: /\[环境\]([\s\S]*?)(?=\[|$)/g,
                template: (content, index) => `
                    <div class="status-card">
                        <div class="status-title" onclick="toggleCard(${index})">
                            🌍 环境
                            <span class="expand-icon">▼</span>
                        </div>
                        <div class="status-content" id="card-${index}">
                            ${formatContent(content)}
                        </div>
                    </div>
                `
            },
            characters: {
                pattern: /\[角色状态\]([\s\S]*?)(?=\[|$)/g,
                template: (content, index) => `
                    <div class="status-card">
                        <div class="status-title" onclick="toggleCard(${index})">
                            👥 角色状态
                            <span class="expand-icon">▼</span>
                        </div>
                        <div class="status-content" id="card-${index}">
                            ${formatContent(content)}
                        </div>
                    </div>
                `
            },
            interaction: {
                pattern: /\[💫关系互动\]([\s\S]*?)(?=\[|$)/g,
                template: (content, index) => `
                    <div class="status-card interaction-card">
                        <div class="status-title" onclick="toggleCard(${index})">
                            💫 关系互动
                            <span class="expand-icon">▼</span>
                        </div>
                        <div class="status-content" id="card-${index}">
                            <div class="interaction-content">
                                ${content.split('\n')
                                    .filter(line => line.trim())
                                    .map(line => `<p class="status-text">${line}</p>`)
                                    .join('')}
                            </div>
                        </div>
                    </div>
                `
            },
            atmosphere: {
                pattern: /\[🎬场景氛围\]([\s\S]*?)(?=\[|$)/g,
                template: (content, index) => `
                    <div class="status-card atmosphere-card">
                        <div class="status-title" onclick="toggleCard(${index})">
                            🎬 场景氛围
                            <span class="expand-icon">▼</span>
                        </div>
                        <div class="status-content" id="card-${index}">
                            <div class="atmosphere-content">
                                ${content.split('\n')
                                    .filter(line => line.trim())
                                    .map(line => `<p class="status-text">${line}</p>`)
                                    .join('')}
                            </div>
                        </div>
                    </div>
                `
            }
        };

        function formatContent(content) {
            return content.split('\n')
                .filter(line => line.trim())
                .map(line => `
                    <div class="status-item">
                        <span class="status-emoji">${line.match(/^[^:：]*/)[0]}</span>
                        <span class="status-text">${line.replace(/^[^:：]*[:：]/, '')}</span>
                    </div>
                `).join('');
        }

        function toggleCard(index) {
            const content = document.getElementById(`card-${index}`);
            content.classList.toggle('expanded');
        }

        function updateStatus(text) {
            let html = '';
            let cardIndex = 0;

            Object.values(rules).forEach(rule => {
                text = text.replace(rule.pattern, (match, content) => {
                    html += rule.template(content, cardIndex++);
                    return '';
                });
            });

            document.getElementById('status-container').innerHTML = html;

            // 自动展开第一个卡片
            setTimeout(() => {
                document.getElementById('card-0').classList.add('expanded');
            }, 100);
        }

